
;

;
import { NOTIFICATIONS_KEY } from "../internal/consts";
import { shallow } from "../../../utils/shallow";
import { resolveAnimate } from "../internal/animate";
import { removeNotificationContainer } from "./container";
import { NOTIFICATION_COLUMN_GAP } from "./styles";
import { NotificationRecords } from "./records";
import type { NotificationEntry } from "./entry";
import { NotificationQueue } from "./queue";
import { NotificationPersistence, readLocalNotifications } from "./storage";
import { applyCardSizes, assembleCard, buildInjectProps, unmountCard } from "./assembly";
import { mergeNotificationProps, settleNotificationLevel, validatePos, validatePersist, type NotificationMergeContext } from "./props";
import { presetComponentName } from "../preset-names";
import {
    parseNotificationProps,
    notificationLevelName,
    NOTIFICATION_DEFAULTS,
    NOTIFICATION_LEVEL_ICONS,
    NOTIFICATION_PERSIST,
    type AutoSparkNotificationRecord,
    type AutoSparkNotificationsOptions,
    type AutoSparkNotificationsState,
    type AutoSparkAction,
    NOTIFICATION_ACTION_TYPES,
    type NotificationOptions,
    type NotificationPos,
    type NotificationProps,
    type ResolvedNotificationAction,
    normalizeActionType,
} from "./types";

export type { NotificationEntry } from "./entry";

/**
 * 事件名段卫生（ADR-0102）：type/id/action 名中的 `/` 与 `*` 会击穿分层结构与通配匹配，
 * 组合具体名时替换为 `-`——事件名仅是广播/匹配键，记录 id 本身不受影响。
 */
function eventSegment(v: unknown): string {
    return String(v ?? "").replace(/[/]/g, "-").replace(/\*/g, "-");
}

/** 组合通知事件具体名（emit 面恒具体；订阅面可 `*`/`**` 通配——ADR-0102） */
function notificationEventName(type: string, id: string, tail: string): string {
    return `notifications/${eventSegment(type)}/${eventSegment(id)}/${tail}`;
}

/**
 * type 种子默认提取（ADR-0089 决策九 + ADR-0092 模板化 → ADR-0094 自 presets.ts 收编）：
 * 种子随组件声明（各 type .html 的 `<script setup>` defaults 段），经标准组件链懒解析提取
 * （`def.defaults`）——用户同名覆盖 type 组件时覆盖组件的 defaults 自然生效（覆盖彻底性）；
 * 未命中 / 组件未声明 defaults 为 undefined（该 type 无种子层）。
 *
 * @param engine 引擎实例（组件查找链）
 * @param type   type 名（toast/task/confirm 或用户扩展 type）
 */
function resolveTypeDefaults(engine: AutoSpark, type: string): Record<string, any> | undefined {
    const name = presetComponentName(type);
    const snapshot = engine._resolveGlobalComponent(name);
    if (!snapshot) return undefined;
    const def = engine.getComponentDef(snapshot) ?? engine.getGlobalComponentDef(name) ?? null;
    return def?.defaults;
}

/** factory 函数类型（ADR-0089：注入 **组件实例**——add 即建，挂起期 methods/data 全程可用） */
export type NotificationSessionFactory = (instance: ComponentInstance) => Promise<NotificationProps | void | undefined>;

/**
 * NotificationManager：全局通知引擎级子系统（ADR-0071 / 0077 / 0083 / 0088 → **ADR-0089 type
 * 组件化**）——编排门面：Map 语义 + API 面 + 事件双通道 + 可见性切换（display 模型）+
 * 组件实例化编排 + 计时与持久化调度。
 *
 * **add 恒返回组件实例**（ComponentInstance——`data` 响应式视图 / `methods` 直调 / `props`
 * 别名；唯一返回物）。可见性纯样式切换：装配即挂 DOM（display:none 挂起/排队）→ 显示 →
 * persist≥1 关闭转隐藏（display:none 保留实例）/ persist=0 与 remove·淘汰真销毁。
 *
 * - **props.ts**——五层合并链 + 归一校验（type 种子经 ctx.typeDefaults 注入，ADR-0089 决策九）；
 * - **records.ts**——entry 构建 / `$notifications` 镜像（纯 record 化，ADR-0089 决策七之三）/
 *   maxLen 淘汰 / 恢复重建；
 * - **assembly.ts**——卡片装配管线（双层装配 + 约定键 watch 联动，ADR-0089）；
 * - **queue.ts**——每 pos 一实例（容量判定 + FIFO 出队；display 切换——补位挂载机制退役）；
 * - **storage.ts**——持久化全责（分桶收集 / 调度 / 删后即刷 / save·load）；
 * - **types/**——内置 type 组件族（一 type 一组件，ADR-0089）。
 *
 * - **Map 语义**（决策 10）：`Map<string, ComponentInstance>`，键恒 string id；可枚举范围 =
 *   全部存活记录（展示中 + 已隐藏）；`delete(id)` = 硬移除（persist 记录一并删 + 立即同步）。
 * - **记录 ⇄ 展示两态分离**（决策 5）：`persist` 0（默认）关闭即删；`1` 会话缓冲 / `2`/`3`
 *   （local/remote）关闭转「已隐藏」态（display:none 保留实例，`show(id)` 直切可见）。
 * - **原地更新**（决策 7）：同 id 重复 add = 换展示 props（注水刷新）+ 重置计时。
 */
export class NotificationManager extends Map<string, ComponentInstance> {
    readonly engine: AutoSpark<any>;
    /** 特性开关（options.notifications !== false）；false 时构造即短路 */
    readonly enabled: boolean;

    /**
     * persist 语义常量（纯闭包产物运行时暴露点，ADR-0004）：IIFE 全局名退役后，
     * NOTIFICATION_PERSIST 经 `engine.notifications.PERSIST` 取用（时序随 ready 挂载，
     * 消费点均在 AutoSpark.ready 内）。
     */
    readonly PERSIST = NOTIFICATION_PERSIST;

    /** 记录域（entry 构建 / 镜像 / 淘汰 / 恢复） */
    readonly records: NotificationRecords;
    /** 持久化域（收集 / 调度 / 即刷 / save·load） */
    readonly storage: NotificationPersistence;

    /** 全部运行时 entry 的私有注册表（id → entry；Map 公共面 value = 组件实例） */
    private _entries = new Map<string, NotificationEntry>();

    /** entry 内部取用（协作部件口——storage/records/queue 经 manager 实例回触） */
    _entryOf(id: string): NotificationEntry | undefined {
        return this._entries.get(id);
    }

    /**
     * $notifications 状态容器（ADR-0072；`notifications: false` 时恒 null）。options 真身：
     * manager 运行时一律经 `_options` 现读 state——state 即配置唯一存放地。
     */
    private _state: AutoSparkNotificationsState | null = null;

    /** 协作部件读取口（records / queue / storage——ADR-0088 模块拆分） */
    get _stateRef(): AutoSparkNotificationsState | null {
        return this._state;
    }

    /** 生效全局配置真身读取（唯一出口；enabled 时恒可用；协作部件同用） */
    get _options(): AutoSparkNotificationsOptions {
        return this._state!.options;
    }

    /** anchor / actions 的全局默认（ADR-0072 边界键）：构造期私有固化——DOM 引用与函数值不入 state */
    private _frozen: { anchor?: NotificationProps["anchor"]; actions?: AutoSparkAction[] } = {};

    /** 自动 id 计数器（records 恢复路径共用） */
    _autoId = 0;

    /** 分区等待队列（按 pos 一实例，ADR-0088）：满员排队，补位按队首 FIFO */
    private _queues = new Map<NotificationPos, NotificationQueue>();

    constructor(engine: AutoSpark<any>) {
        super();
        this.engine = engine;
        const cfg = (engine.options as any).notifications;
        this.enabled = cfg !== false;
        const user: NotificationOptions = cfg === false || cfg == null ? {} : cfg;
        this._frozen = { anchor: user.anchor, actions: user.actions };
        this.records = new NotificationRecords(this);
        this.storage = new NotificationPersistence(this);
        if (!this.enabled) return; // notifications: false——不注入保留键、不恢复
        // $notifications 保留键注入（永不整体替换容器）：options 真身 = 内置默认 < 用户配置
        // （剥 anchor/actions 两边界键）；items 纯 record 化（ADR-0089 决策七之三）
        const effective: Record<string, any> = {};
        for (const key of Object.keys(user)) {
            if (key !== "anchor" && key !== "actions") effective[key] = (user as any)[key];
        }
        for (const key of Object.keys(NOTIFICATION_DEFAULTS)) {
            if (effective[key] === undefined) effective[key] = (NOTIFICATION_DEFAULTS as any)[key];
        }
        const shallowDepth: 0 | 1 = Number(effective.shallow) === 0 ? 0 : 1;
        (engine.store.state as Record<string, any>)[NOTIFICATIONS_KEY] = {
            items: shallow<AutoSparkNotificationRecord[], 0 | 1>([], shallowDepth) as AutoSparkNotificationsState["items"],
            options: effective as AutoSparkNotificationsOptions,
        };
        this._state = (engine.store.state as Record<string, any>)[NOTIFICATIONS_KEY] as AutoSparkNotificationsState;
        // local 持久化的启动恢复（决策 18）：只入记录（隐藏态 display:none）、不自动重弹
        this.records.restoreRecords(
            readLocalNotifications((m) => this.engine.logger.warn(m)),
            "local",
        );
    }

    // ── 显示入口（决策 7 三态入参；ADR-0089 恒返回组件实例） ─────────────

    /**
     * 添加一条通知（字符串简写 ≡ `{ title }`；factory resolve `undefined` → 静默销毁）。
     * **恒返回组件实例**（add 即装配挂 DOM——display:none 挂起/排队态）。同 id = 原地更新。
     *
     * 第二参（ADR-0089 决策八）：**factory 形态的类型声明 + 初始 props**——`'task'`（type 名）
     * 或 `{ type: 'task', canCancel: true, … }`（对象形态携初始配置，实例化同刻注水——
     * `instance.data._abort.signal` 等在 factory 闭包内即可用）。非 factory 形态携带 → warn 忽略。
     */
    add(input: string | NotificationProps | NotificationSessionFactory, second?: string | NotificationProps): ComponentInstance | null {
        if (!this.enabled) {
            this.engine.logger.warn("engine.notifications: 通知特性已通过 options.notifications: false 关闭，调用被忽略");
            return null;
        }
        if (typeof input === "function") return this._addAsync(input, second);
        if (second != null) {
            this.engine.logger.warn(
                `engine.notifications: add(..., ${typeof second === "string" ? `"${second}"` : "props"}) 第二参仅对 factory 形态生效（对象形态请用 type 字段），已忽略`,
            );
        }
        const parsed = parseNotificationProps(input, (m) => this.engine.logger.warn(m));
        if (!parsed) return null;
        return this._enqueueProps(parsed);
    }

    /**
     * async factory 形态（ADR-0089 决策八——**真实例，预句柄/缓存机制退役**）：同步装配
     * （display:none 挂起态）并把**组件实例**注入 factory——挂起期 methods/data 全程可用
     * （`progress()` 直写 data 域）。resolve props = 初始展示配置（走注水刷新——运行约定键
     * 剥离不回拨闭包已推值；`undefined` → 静默销毁；缺 title → warn 销毁）。**主用法 = 立即
     * return**（即时卡 + 后台驱动：长任务不 await 主线，`inst` 闭包存活持续驱动——
     * 「后台静默跑完才弹卡」不是目标形态，ADR-0083 二次修订沿用）。
     */
    private _addAsync(factory: NotificationSessionFactory, second?: string | NotificationProps): ComponentInstance | null {
        const seedProps: NotificationProps =
            second != null && typeof second === "object" ? second : ({} as NotificationProps);
        const declared =
            second == null ? "toast" : typeof second === "string" ? String(second).trim() || "toast" : String(seedProps.type ?? "").trim() || "toast";
        const { merged, type } = this._mergeProps({ ...seedProps, type: declared });
        validatePos(merged, (m) => this.engine.logger.warn(m));
        this._settleLevel(merged);
        validatePersist(merged, (m) => this.engine.logger.warn(m));
        const id = merged.id != null && merged.id !== "" ? String(merged.id) : `notification-${++this._autoId}`;
        merged.id = id; // 写回生效配置（注水面 / this.props.id 数据源——ADR-0089 无 session 回填通道）
        merged.type = type; // 同上（instance.type / this.props.type 数据源）
        const entry = this.records.createEntry(merged as NotificationProps, id, type);
        if (!this._materialize(entry)) return null; // 装配 + 入表（SSR 无容器 → null）
        const instance = entry.instance;
        void (async () => {
            try {
                const props = await factory(instance!);
                if (!this._entries.has(id) || entry.state === "closed") return; // 挂起期 hide()/cancel() = 丢弃
                if (props == null) {
                    this._destroyEntry(entry); // 条件通知：内容不就绪，静默销毁
                    return;
                }
                const parsed = parseNotificationProps(
                    typeof props === "string" ? props : (props as NotificationProps),
                    (m) => this.engine.logger.warn(m),
                );
                if (!parsed || !String((parsed as NotificationProps).title ?? "").trim()) {
                    this.engine.logger.warn("engine.notifications: factory 结果缺少 title（空通知），已销毁");
                    this._destroyEntry(entry);
                    return;
                }
                // type 锁定（ADR-0083 修订）：显式声明的 type 优先——组件已按声明实例化，不可变
                if (parsed.type != null && String(parsed.type) !== declared) {
                    this.engine.logger.warn(
                        `engine.notifications: factory 声明 type "${declared}" 与 return props type "${parsed.type}" 不一致，以声明为准（类型不可变）`,
                    );
                    parsed.type = declared as NotificationProps["type"];
                }
                const fresh = this._mergeProps({ ...parsed, id, type: declared }).merged;
                this._applyEntryConfig(entry, fresh as NotificationProps);
                entry.state = "queued";
                this._emit("add", entry);
                this._displayEntry(entry);
                this.storage.schedule();
            } catch (e: any) {
                this.engine.logger.warn(`engine.notifications: factory 执行失败，已销毁: ${e?.message ?? e}`);
                this._destroyEntry(entry);
            }
        })();
        return instance;
    }

    /** entry 物化：装配（display:none）+ choice 绑定 + 入表 + 镜像 + 淘汰；失败（SSR）false。
     *  （`_` 内部面——records 恢复路径共用） */
    _materialize(entry: NotificationEntry): boolean {
        if (!assembleCard(this, entry)) return false;
        this._bindChoice(entry);
        this._entries.set(entry.id, entry);
        super.set(entry.id, entry.instance!);
        this.records.mirrorAdd(entry);
        this.records.evictOverflow(entry);
        return true;
    }

    /** confirm choice 闭环（ADR-0077/0083）：choice promise + 实例附加 then（thenable——await 实例即得应答） */
    private _bindChoice(entry: NotificationEntry): void {
        if (entry.type !== "confirm" || !entry.instance) return;
        const choice = new Promise<any>((resolve) => {
            entry.confirmResolve = resolve;
        });
        Object.defineProperty(entry.instance, "then", {
            value: choice.then.bind(choice),
            configurable: true,
        });
    }

    /** type 种子默认缓存（ADR-0092）：type 名 → 组件 defaults（undefined = 已查明无种子层） */
    private _typeDefaultsCache = new Map<string, Record<string, any> | undefined>();
    /**
     * type 种子默认视图（ADR-0089 决策九 + ADR-0092 模板化）：种子随组件声明（各 type .html 的
     * `<script setup>` defaults 段），经组件表懒解析提取（resolveTypeDefaults）+ 本缓存去重——
     * 用户同名覆盖 type 组件时覆盖组件的 defaults 自然生效。Proxy 保持 mergeNotificationProps 的
     * `typeDefaults[type]` 消费形态不变。
     */
    private readonly _typeDefaults: Record<string, Record<string, any>> = new Proxy(
        {} as Record<string, Record<string, any>>,
        {
            get: (_t, type: string | symbol): Record<string, any> | undefined => {
                if (typeof type !== "string") return undefined;
                if (!this._typeDefaultsCache.has(type)) {
                    this._typeDefaultsCache.set(type, resolveTypeDefaults(this.engine, type));
                }
                return this._typeDefaultsCache.get(type);
            },
        },
    );

    /** 合并链上下文（props.ts mergeNotificationProps 的 manager 侧入参组装——type 种子经此注入） */
    private _mergeCtx(): NotificationMergeContext {
        return {
            opts: this.enabled ? this._options : ({} as AutoSparkNotificationsOptions),
            frozen: this._frozen,
            typeDefaults: this._typeDefaults,
            warn: (m: string) => this.engine.logger.warn(m),
        };
    }

    /** 五层合并链委托（props.ts）——records / update 路径共用 */
    _mergeProps(userProps: NotificationProps): { merged: Record<string, any>; type: string } {
        return mergeNotificationProps(userProps, this._mergeCtx());
    }

    /** level 归一委托（props.ts） */
    _settleLevel(merged: Record<string, any>): void {
        settleNotificationLevel(merged, (m) => this.engine.logger.warn(m));
    }

    /** 入队 / 原地更新（同 id）唯一入口：合并链 → 校验 → 已存在则更新，否则物化 + 容量判定 */
    private _enqueueProps(userProps: NotificationProps): ComponentInstance | null {
        if (!String(userProps.title ?? "").trim()) {
            this.engine.logger.warn("engine.notifications: title 为空，调用被忽略");
            return null;
        }
        const { merged, type } = this._mergeProps(userProps);
        validatePos(merged, (m) => this.engine.logger.warn(m));
        this._settleLevel(merged);
        validatePersist(merged, (m) => this.engine.logger.warn(m));
        const id = merged.id != null && merged.id !== "" ? String(merged.id) : `notification-${++this._autoId}`;
        merged.id = id; // 写回生效配置（注水面数据源——ADR-0089 无 session 回填通道）
        merged.type = type; // 同上（instance.type / this.props.type 数据源）

        // 同 id 处理（决策 5/7）：queued/shown → 原地更新；hidden/closed → 换新配置重显
        const existing = this._entries.get(id);
        if (existing) {
            if (existing.state === "shown" || existing.state === "queued") {
                this._updateInPlace(existing, userProps);
                return this.get(id) ?? null;
            }
            const fresh = this._mergeProps({ ...merged, id }).merged;
            this._applyEntryConfig(existing, fresh as NotificationProps);
            existing.state = "queued";
            this._displayEntry(existing);
            this.storage.schedule();
            return this.get(id) ?? null;
        }

        const entry = this.records.createEntry(merged as NotificationProps, id, type);
        if (!this._materialize(entry)) return null; // 装配 + 入表（SSR 无容器 → null）
        this._emit("add", entry);
        this._displayEntry(entry);
        this.storage.schedule();
        return entry.instance;
    }

    // ── 配套解析（icon / anchor / actions——records 与原地更新共用） ────

    /** 同屏上限（管理器级键，不进合并链；state 真身现读——运行时改即刻生效） */
    get _showCount(): number {
        const n = this._state?.options.showCount ?? NOTIFICATION_DEFAULTS.showCount;
        return typeof n === "number" && n > 0 ? Math.floor(n) : NOTIFICATION_DEFAULTS.showCount;
    }

    /** 存活记录数上限（0 = 不限；state 真身现读，ADR-0072 起支持运行时修改） */
    get _maxLen(): number {
        const n = this._state?.options.maxLen;
        return typeof n === "number" && n > 0 ? Math.floor(n) : 0;
    }

    /** level → 图标名：显式 icon > icons 重映射 > 同名词默认；none(0) 无图标 */
    _resolveIcon(level: number, explicit?: string): string {
        if (explicit) return explicit;
        if (level === 0) return "";
        const name = notificationLevelName(level as any) as Exclude<ReturnType<typeof notificationLevelName>, "none">;
        return this._options.icons?.[name] ?? NOTIFICATION_LEVEL_ICONS[name] ?? name;
    }

    /** anchor 归一化（决策 14）：string = add 时一次性 querySelector，未命中 warn + null */
    _resolveAnchor(anchor: NotificationProps["anchor"]): HTMLElement | null {
        if (anchor == null) return null;
        if (anchor instanceof HTMLElement) return anchor;
        if (typeof anchor === "string") {
            const el = typeof document !== "undefined" ? document.querySelector(anchor) : null;
            if (!el) {
                this.engine.logger.warn(`engine.notifications: anchor 选择器 "${anchor}" 未命中，按无 anchor 处理`);
                return null;
            }
            return el as HTMLElement;
        }
        return null;
    }

    /** actions 预解析（决策 13/14）：字符串查 action 表（anchor 沿 scope 链），对象形态解析 value/handle/hide/type */
    _resolveActions(items: AutoSparkAction[] | undefined, anchor: HTMLElement | null): ResolvedNotificationAction[] {
        const resolved: ResolvedNotificationAction[] = [];
        // 语义变体归一（ADR-0129）：非法值 warn 后忽略（按钮回退 level accent 着色）
        const actionType = (raw: any, label: string) => {
            const t = normalizeActionType(raw?.type);
            if (raw?.type !== undefined && t === undefined) {
                this.engine.logger.warn(
                    `engine.notifications: action "${label}" 的 type 须为 ${NOTIFICATION_ACTION_TYPES.join("/")}，已忽略（按钮色回退跟随 level）`,
                );
            }
            return t;
        };
        for (const item of items ?? []) {
            if (typeof item === "string") {
                const desc = this._resolveActionByName(item, anchor);
                if (!desc) {
                    this.engine.logger.warn(
                        `engine.notifications: action "${item}" 未命中（全局表${anchor ? "与 anchor scope 链" : ""}），按钮已剪枝`,
                    );
                    continue;
                }
                resolved.push({
                    name: item,
                    title: (desc.title as string) ?? item,
                    handle: desc.handle,
                    hide: (desc as any).hide !== false,
                    hasValue: false,
                    value: undefined,
                    type: actionType(desc, item),
                });
            } else if (item && typeof item === "object") {
                const hasValue = "value" in item;
                resolved.push({
                    name: String((item as any).id ?? (item as any).title ?? "action"),
                    title: (item as any).title ?? "action",
                    handle: typeof (item as any).handle === "function" ? (item as any).handle : null,
                    hide: (item as any).hide !== false,
                    hasValue,
                    value: (item as any).value,
                    type: actionType(item, String((item as any).title ?? "action")),
                });
            } else {
                this.engine.logger.warn("engine.notifications: 非法 action 项，已剪枝");
            }
        }
        return resolved;
    }

    /** 字符串 action 解析：anchor 存在时沿其向上 scope 链逐级现查，未命中回退全局表 */
    private _resolveActionByName(name: string, anchor: HTMLElement | null) {
        if (anchor) {
            let el: HTMLElement | null = anchor;
            while (el) {
                const scope = this.engine.findScopeByEl(el);
                const desc = scope?.getAction(name);
                if (desc) return desc;
                el = el.parentElement;
            }
        }
        return this.engine.actions[name];
    }

    // ── 原地更新（决策 7）与记录级写通道（决策 8） ─────────────────────

    /** 同 id 重复 add：以 entry 当前生效配置为基准、userProps 显式键打补丁；重置计时、不重播动画 */
    private _updateInPlace(entry: NotificationEntry, userProps: NotificationProps): void {
        if ("type" in userProps && String(userProps.type) !== entry.type) {
            this.engine.logger.warn("engine.notifications: 同 id 更新不支持变更 type，已忽略");
        }
        const merged: Record<string, any> = { ...entry.props };
        // ADR-0088 整包直传：补丁键全量并入；id / type / pos / offset 恒不变
        for (const key of Object.keys(userProps)) {
            if (key === "id" || key === "type" || key === "pos" || key === "offset") continue;
            merged[key] = (userProps as any)[key];
        }
        validatePos(merged, (m) => this.engine.logger.warn(m));
        this._applyEntryConfig(entry, merged as NotificationProps);
        if (entry.state === "shown") this._startTimer(entry); // 重置满额计时
        this._emit("update", entry);
        this.storage.schedule();
    }

    /**
     * 应用新配置到 entry（level 归一 + 业务键同步 record + icon/actions 派生 + 注水刷新 +
     * className/styles 换装）。**注水面剥运行约定键**（progress/paused/completed——运行态唯
     * 组件 data 域是尊，闭包已推值不被 return props / update 补丁回拨，ADR-0089 决策八）；
     * `progress` 显式补丁经组件 method 应用（paused/completed 守卫内建）。
     */
    _applyEntryConfig(entry: NotificationEntry, props: NotificationProps): void {
        const prevClassName = entry.appliedClassName;
        const prevStyles = entry.appliedStyles;
        this._settleLevel(props as Record<string, any>);
        entry.props = props;
        for (const key of ["title", "description", "owner", "status", "result", "link", "read"] as const) {
            if (key in props) (entry.record as any)[key] = (props as any)[key];
        }
        entry.record.level = props.level as any;
        this.records.touch(entry);
        entry.icon = this._resolveIcon(entry.record.level ?? 0, props.icon);
        entry.actions = this._resolveActions(props.actions, entry.anchor);
        // 注水刷新（数据域响应式活体红利；ADR-0095 单层化——实例 scope 即卡片 scope，一次注水）
        const inject = buildInjectProps(this, entry);
        if (entry.instance) Object.assign(entry.instance.data, inject);
        // progress 补丁通道（update(id, { progress }) 同路——组件 method 守卫内建）
        if (props.progress != null && entry.instance) {
            entry.instance.methods.progress?.(Number(props.progress));
        }
        const nextClassName = props.className ? String(props.className).trim() : "";
        const nextStyles = props.styles ? String(props.styles) : "";
        if (entry.el) {
            if (prevClassName) entry.el.classList.remove(...prevClassName.split(/\s+/));
            if (nextClassName) entry.el.classList.add(...nextClassName.split(/\s+/));
            if (nextStyles !== prevStyles) {
                entry.el.style.cssText = nextStyles; // cssText 整写清空旧 inline，尺寸键随后重放
            }
            // 尺寸五键每次换装重放（幂等——只挂 styles 分支会漏掉裸 width 等渲染键的原地更新）
            applyCardSizes(entry.el, props);
            // data-notification-level 不在此静态写（ADR-0095 契约绑定化）：level 已随注水刷新
            // 进 shell 实例 data 域，模板 `:data-notification-level` 绑定响应式跟随
        }
        entry.appliedClassName = nextClassName;
        entry.appliedStyles = nextStyles;
        this.records.mirrorReplace(entry); // 记录级变更 → 镜像整替换（纯 record 面）
    }


    /**
     * 记录级字段唯一写通道（决策 8）：`read` / `status` / `result` / `title` / `level` 等补丁
     * 生效 = 改记录 + 发 `update` 事件（分层名 `notifications/<type>/<id>/update`）+ 触发持久化。id / type 不可变。
     */
    update(id: string, patch: Partial<NotificationProps>): void {
        const entry = this._entries.get(id);
        if (!entry || !this._entries.has(id)) {
            this.engine.logger.warn(`engine.notifications: update("${id}") 未命中存活记录，已忽略`);
            return;
        }
        parseNotificationProps(patch as NotificationProps, (m) => this.engine.logger.warn(m));
        if ("type" in patch && String(patch.type) !== entry.type) {
            this.engine.logger.warn("engine.notifications: update 不支持修改 type，已忽略");
        }
        const prevRead = entry.props.read === true;
        const prevStatus = entry.props.status;
        const merged: Record<string, any> = { ...entry.props };
        for (const key of Object.keys(patch)) {
            if (key === "id" || key === "type" || key === "pos" || key === "offset") continue;
            merged[key] = (patch as any)[key];
        }
        validatePos(merged, (m) => this.engine.logger.warn(m));
        this._applyEntryConfig(entry, merged as NotificationProps);
        this._emit("update", entry);
        if (!prevRead && entry.props.read === true) this._emit("read", entry);
        if (entry.props.status !== prevStatus) this._emit("status", entry);
        this.storage.schedule();
    }

    // ── 已读（决策 11） ───────────────────────────────────────────────

    /** 置已读（幂等）：卡片任意点击自动调用；变更时发 `read` 事件 + 持久化 + 镜像替换 */
    private _setRead(entry: NotificationEntry): void {
        if (entry.props.read === true) return;
        entry.props.read = true;
        entry.record.read = true;
        this.records.touch(entry);
        if (entry.instance) entry.instance.data.read = true;
        this.records.mirrorReplace(entry);
        this._emit("read", entry);
        this.storage.schedule();
    }

    /** 编程式置已读 */
    markRead(id: string): void {
        const entry = this._entries.get(id);
        if (!entry) {
            this.engine.logger.warn(`engine.notifications: markRead("${id}") 未命中存活记录，已忽略`);
            return;
        }
        this._setRead(entry);
    }

    /** 按 type 批量置已读（缺省全量） */
    markAllRead(type?: string): void {
        for (const entry of Array.from(this._entries.values())) {
            if (entry.props.read !== true && (type == null || entry.type === type)) {
                this._setRead(entry);
            }
        }
    }

    // ── 展示编排（display 模型，ADR-0089 决策四；queue 分区收口） ───────

    /** 分区队列取（或懒建） */
    private _queueOf(pos: NotificationPos): NotificationQueue {
        let q = this._queues.get(pos);
        if (!q) {
            q = new NotificationQueue(this, pos);
            this._queues.set(pos, q);
        }
        return q;
    }

    /** 容量判定入口（queue.offer 收口：有坑 display 切换显示 / 满员排队） */
    _displayEntry(entry: NotificationEntry): void {
        this._queueOf(entry.props.pos as NotificationPos).offer(entry);
    }

    /**
     * 显示（display 切换 + 进场动画 + 计时启动 + visible 约定键）——queue 与 show(id) 共用。
     */
    _showEntry(entry: NotificationEntry): void {
        if (entry.state === "shown") return;
        if (entry.el) entry.el.style.display = "";
        entry.state = "shown";
        if (entry.instance) {
            entry.instance.data.visible = true;
            entry.instance.data.closed = false;
        }
        if (entry.el) this.engine.animate.enter(entry.el, resolveAnimate(entry.props.animate).enter);
        this._startTimer(entry);
        this._emit("show", entry);
        this._emitTaskAutoStart(entry);
    }

    /** 出等待队列（关闭前置——防止补位显示已关闭 entry） */
    _dequeue(entry: NotificationEntry): void {
        this._queues.get(entry.props.pos as NotificationPos)?.remove(entry);
    }

    /** 补位：该分区有空坑时按队首 FIFO 显示等待队列 */
    _flushQueue(pos: NotificationPos): void {
        this._queueOf(pos).flush();
    }

    // ── 重显（决策 9）与 add 别名 ────────────────────────────────────

    /**
     * `add` 的别名：配置对象 / async factory 直转 `add(...)`（含第二参透传）。**string 形态
     * 保留重显语义**：已隐藏记录 display 直切可见（重走进场动画与计时）；展示中幂等 no-op；
     * 不存在 warn + null。
     */
    show(input: string | NotificationProps | NotificationSessionFactory, second?: string | NotificationProps): ComponentInstance | null {
        if (typeof input !== "string") return this.add(input, second);
        if (second != null) {
            this.engine.logger.warn(`engine.notifications: show("${input}", ...) 第二参仅对 factory 形态生效，已忽略`);
        }
        const entry = this._entries.get(input);
        if (!entry || entry.state === "closed") {
            this.engine.logger.warn(`engine.notifications: show("${input}") 未命中存活记录（persist=0 的已关通知已销毁）`);
            return null;
        }
        if (entry.state === "shown" || entry.state === "queued") return this.get(input) ?? null; // 幂等
        entry.state = "queued";
        this._displayEntry(entry);
        return this.get(input) ?? null;
    }

    /** 关闭（走离场动画；幂等；排队/挂起中 = 出队后收口）——base 组件 methods 的公共落点 */
    hide(id: string): void {
        const entry = this._entries.get(id);
        if (entry && entry.state !== "closed" && entry.state !== "hidden") {
            this._dismiss(entry, true);
        }
    }

    // ── type 快捷方式（ADR-0077：show 统一入口上的便捷层，均强制对应 type） ──

    /** toast 快捷方式：≡ `show({ ...props, type: 'toast' })` */
    toast(props: string | NotificationProps | NotificationSessionFactory): ComponentInstance | null {
        if (typeof props === "function") {
            return this.show(async (instance) => {
                const resolved = await props(instance);
                return resolved == null ? undefined : { ...resolved, type: "toast" };
            }, "toast");
        }
        const initial = { ...(typeof props === "string" ? { title: props } : props), type: "toast" };
        return this.show(initial);
    }

    /**
     * confirm 快捷方式：≡ `show({ ...props, type: 'confirm', delayClose: 0, 双钮 })`——返回
     * **thenable 组件实例**（`await` 直接得 choice 应答，sticky 永不 settle；`yes()/no()`
     * methods 编程应答）。`{yes, no}` 可提取键（决策 22）从 props 剥离转按钮文案。
     */
    confirm(notification: string | NotificationProps, texts?: { yes?: string; no?: string }): ComponentInstance | null {
        const base: Record<string, any> = typeof notification === "string" ? { title: notification } : { ...notification };
        const yes = texts?.yes ?? base.yes;
        const no = texts?.no ?? base.no;
        delete base.yes; // 可提取键剥离（决策 22）——不落入通知 props
        delete base.no;
        return this.show({
            ...(base as NotificationProps),
            type: "confirm",
            delayClose: base.delayClose ?? 0, // sticky：永不自动关
            actions: (base.actions?.length ? base.actions : undefined) ?? [
                // 语义变体（ADR-0129 场景化语义色，同 actions/confirm.ts 封装）：确定 = 主操作、取消 = 中性弱化
                { title: yes ?? "确定", value: true, type: "primary" },
                { title: no ?? "取消", value: false, type: "plain" },
            ],
        });
    }

    /** task 快捷方式：≡ `show({ ...props, type: 'task' })`——返回 task 组件实例（methods 直调） */
    task(props: string | NotificationProps | NotificationSessionFactory): ComponentInstance | null {
        if (typeof props === "function") {
            return this.show(async (instance) => {
                const resolved = await props(instance);
                return resolved == null ? undefined : { ...resolved, type: "task" };
            }, "task");
        }
        const initial = { ...(typeof props === "string" ? { title: props } : props), type: "task" };
        return this.show(initial);
    }

    // ── 关闭与收口（display 模型：persist 分流，ADR-0089 决策四） ────────

    /**
     * 关闭（一切移除路径终点）：`hide` 事件广播在发起时；离场动画（收拢沿用）完成后按
     * persist 分流——`≥1` 转「已隐藏」（display:none **保留实例**，closed 约定键置位）；
     * `0` 真销毁（`_destroyEntry`）。排队中的 entry 同步出等待队列。
     */
    _dismiss(entry: NotificationEntry, animated: boolean): void {
        if (entry.state === "closed" || entry.state === "hidden") return;
        if (entry.state === "queued") this._dequeue(entry);
        entry.state = "closed";
        this._clearTimer(entry);
        if (entry.instance) {
            entry.instance.data.visible = false;
        }
        this._emit("hide", entry);
        const finish = () => this._settleClose(entry);
        const leave = animated ? entry.leave : null;
        const el = entry.el;
        if (leave && el && el.style.display !== "none") {
            // 收拢起始帧（先于 leave）：锁定自然高度（happy-dom offsetHeight 恒 0 无害）
            el.style.boxSizing = "border-box";
            el.style.height = `${el.offsetHeight}px`;
            el.style.overflow = "hidden";
            const started = this.engine.animate.leave(el, leave, finish);
            if (!started) {
                finish();
            } else {
                // 收拢目标帧：布局高度平滑归零、兄弟随流上移（ADR-0068 离场收拢沿用）
                el.style.transitionProperty =
                    "transform, opacity, height, padding-top, padding-bottom, margin-bottom, border-top-width, border-bottom-width";
                el.style.height = "0px";
                el.style.paddingTop = "0px";
                el.style.paddingBottom = "0px";
                el.style.marginBottom = `${-NOTIFICATION_COLUMN_GAP}px`;
                el.style.borderTopWidth = "0px";
                el.style.borderBottomWidth = "0px";
            }
        } else {
            finish();
        }
    }

    /** 关闭收口（动画完成后）：persist ≥ 1 转隐藏（display:none 保留）；否则真销毁 */
    private _settleClose(entry: NotificationEntry): void {
        const persist = Number(entry.props.persist ?? NOTIFICATION_PERSIST.NONE);
        this._queueOf(entry.props.pos as NotificationPos).releaseShown(entry.id);
        if (persist >= NOTIFICATION_PERSIST.SESSION && persist <= NOTIFICATION_PERSIST.REMOTE) {
            entry.state = "hidden"; // 记录存活（display:none 保留实例，show(id) 直切可见）
            if (entry.el) entry.el.style.display = "none";
            if (entry.instance) {
                entry.instance.data.closed = true;
                entry.instance.data.visible = false;
            }
        } else {
            this._destroyEntry(entry); // toast 兼容语义：关闭即销毁
        }
        this._flushQueue(entry.props.pos as NotificationPos);
        this.storage.schedule();
    }

    /** 真销毁（remove/淘汰/persist=0 关闭/factory 丢弃）：摘 DOM + 双 scope 收口 + 出表 + 镜像删。
     *  （`_` 内部面——records 淘汰路径共用） */
    _destroyEntry(entry: NotificationEntry): void {
        if (entry.state === "queued") this._dequeue(entry);
        entry.state = "closed";
        this._clearTimer(entry);
        entry.confirmResolve = null;
        unmountCard(this, entry);
        this._entries.delete(entry.id);
        super.delete(entry.id);
        this.records.mirrorRemove(entry.id);
        this._queueOf(entry.props.pos as NotificationPos).releaseShown(entry.id);
    }

    // ── Map 覆写与批量操作（决策 10） ──────────────────────────────────

    /**
     * 覆写 `Map.delete`：**硬移除**（无动画 + persist 记录一并删）+ **立即同步持久化**
     * （local 即写、remote 即 flush——「删干净」闭环）。展示中/排队中先广播 `hide` 事件
     * （决策 20：一切移除路径均广播——payload.notification 在销毁前取）。
     */
    override delete(id: string): boolean {
        const entry = this._entries.get(id);
        if (!entry) return false;
        if (entry.state === "shown" || entry.state === "queued") this._emit("hide", entry);
        this._destroyEntry(entry);
        this._flushQueue(entry.props.pos as NotificationPos);
        this.storage.flushNow();
        return true;
    }

    /** 覆写 `Map.clear`：清全部存活记录（含隐藏），默认带离场动画；立即同步持久化 */
    override clear(animated: boolean = true): void {
        for (const q of this._queues.values()) q.clear(); // 先清等待队列（防 dismiss 补位显示排队 entry）
        for (const entry of Array.from(this._entries.values())) {
            if (entry.state === "shown" || entry.state === "queued") {
                this._dismiss(entry, animated);
            } else {
                this._destroyEntry(entry); // 隐藏态直销（display 模型下仍在 DOM）
            }
        }
        if (this._state) this._state.items.splice(0); // 镜像清空
        this.storage.flushNow();
    }

    /** engine.destroy() 收口：全部立即销毁 + 容器整体移除 + 持久化 flush。
     *  （flush 先于销毁——collect 遍历存活记录，先删后收会写空载荷） */
    dispose(): void {
        this.storage.flushNow();
        for (const q of this._queues.values()) q.clear();
        for (const entry of Array.from(this._entries.values())) {
            if (entry.state === "shown" || entry.state === "queued" || entry.state === "hidden") {
                this._destroyEntry(entry);
            }
        }
        removeNotificationContainer(this.engine);
        if (this._state) this._state.items.splice(0); // 镜像清空（引擎收口——Map 与镜像同步归零）
    }

    // ── 持久化与拉取（storage 域委托，ADR-0088） ───────────────────────

    /** 从服务器拉取通知（决策 17）：GET JSON 数组、按 id 覆盖合并、只入记录不弹 */
    async load(url?: string): Promise<ComponentInstance[]> {
        return this.storage.load(url);
    }

    /** 立即持久化 flush（决策 18）：local 同步写 + remote 立即 POST */
    async save(): Promise<void> {
        await this.storage.save();
    }

    // ── 交互闭环（决策 13/11） ─────────────────────────────────────────

    /** 卡片点击委托：任意点击置已读（决策 11）→ action 按钮（value 闭环）→ 关闭钮 */
    _onCardClick(entry: NotificationEntry, e: Event): void {
        this._setRead(entry);
        const target = e.target as Element | null;
        const actionBtn = target?.closest?.(".autospark-notification-action") as HTMLElement | null;
        if (actionBtn) {
            const index = Number(actionBtn.getAttribute("data-notification-action"));
            const action = entry.actions[Number.isInteger(index) ? index : -1];
            if (action) this._fireAction(entry, action);
            return;
        }
        if (target?.closest?.(".autospark-notification-close")) {
            // × 语义（ADR-0102 → ADR-0104 修订为独立 close 动词）：优先组件 close()——task
            // 覆写为「非终态先 abort + actions/close 广播再关」；无 close 的 type 回落
            // cancel()（shell ≡ hide——既有行为零变化）；均无则直关
            const methods = (entry.instance?.methods ?? {}) as Record<string, unknown>;
            const routed =
                typeof methods.close === "function" ? methods.close : typeof methods.cancel === "function" ? methods.cancel : null;
            if (typeof routed === "function") (routed as () => void)();
            else this._dismiss(entry, true);
        }
    }

    /**
     * action 触发闭环（决策 13，按钮点击与 confirm `yes()/no()` / `respond()` 共用）：value 写
     * result → `actions/<名>` 事件广播 → confirm resolve → handle → hide 判定。
     */
    _fireAction(entry: NotificationEntry, action: ResolvedNotificationAction): void {
        if (action.hasValue) {
            entry.props.result = action.value;
            entry.record.result = action.value;
            this.records.touch(entry);
            if (entry.instance) entry.instance.data.result = action.value;
            this.records.mirrorReplace(entry);
        }
        this._emitAction(entry, action);
        if (entry.confirmResolve) {
            entry.confirmResolve(action.hasValue ? action.value : undefined);
            entry.confirmResolve = null;
        }
        action.handle?.();
        this.storage.schedule();
        if (action.hide) this._dismiss(entry, true);
    }

    /**
     * Confirm 选择（`yes()/no()` ≡ 点击对应 value 按钮 / `respond(id, value)` 同路）——沿
     * `_fireAction` 同一闭环。无匹配 action（actions 被自定义清空）→ warn + no-op。
     */
    _fireConfirmChoice(entry: NotificationEntry, value: boolean): void {
        const action = entry.actions.find((a) => a.hasValue && a.value === value);
        if (!action) {
            this.engine.logger.warn(
                `engine.notifications: type='confirm' 会话缺少 value=${value} 的按钮（actions 已被自定义），选择无效（ADR-0077）`,
            );
            return;
        }
        this._fireAction(entry, action);
    }

    /** 编程应答（ADR-0083 Q6a）：`respond(id, true)` ≡ 点击对应 value 按钮 */
    respond(id: string, value: any): void {
        const entry = this._entries.get(id);
        if (!entry) {
            this.engine.logger.warn(`engine.notifications: respond("${id}") 未命中存活记录，已忽略`);
            return;
        }
        this._fireConfirmChoice(entry, value);
    }

    // ── 任务控制动词（ADR-0104） ─────────────────────────────────────

    /**
     * 控制动词事件派发（ADR-0104）：`notifications/<type>/<id>/actions/<动词>`——task 内置
     * 控制钮（开始/暂停/恢复/停止/取消）与 × 关闭共用 props.actions 的 action 事件家族
     * （内置动词 start/pause/resume/stop/cancel/close 为该卡 actions 命名空间的事实保留
     * 名）。**方法级单一真相源**：组件方法内调用——按钮点击与程序直调（`session.pause()`)
     * 同发，外部可模拟用户操作。payload `{ notification, el }`（无 value——控制动词无应答）。
     */
    _emitControlAction(id: string, verb: string): void {
        const entry = this._entries.get(id);
        if (!entry) return;
        const name = notificationEventName(entry.type, entry.props.id, `actions/${verb}`);
        const detail = { notification: entry.instance as ComponentInstance, el: entry.el };
        this.engine.emit(name, detail as any);
        entry.el?.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
        if (entry.anchor) {
            entry.anchor.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
        }
    }

    /**
     * 控制动词订阅（ADR-0104 onXxx 便捷面的引擎侧落点）：具体名订阅（精确名回调收
     * `{type, payload}` 信封——`session.onPause(cb)` 等转发至此）+ 退订函数登记
     * `entry.controlOffs`（unmountCard 自动清）。返回**退订函数**（fastevent 订阅者
     * 对象的 `.off()` 包装——调用方提前手动退订用）。
     */
    _onControlAction(id: string, verb: string, cb: (payload: any) => void): () => void {
        const entry = this._entries.get(id);
        const name = notificationEventName(entry?.type ?? "task", id, `actions/${verb}`);
        const subscriber = this.engine.on(name, cb as any);
        const off = () => subscriber.off();
        if (entry) entry.controlOffs.push(off);
        return off;
    }

    /**
     * 自动模式 start 补发（ADR-0104 决策 1c）：未声明 canStart 的 task 自动开跑，**首次
     * 显示时**补发一次 `actions/start`——时机在 show 事件后（factory 闭包内挂的 onStart
     * 不丢事件）；重显（persist ≥ 1 hide → show）不重发。手动门控卡（canStart）的 start
     * 归「开始」钮 / `start()`；显示前已入终态（闭包抢跑完成/停止）不补发——生命周期已由
     * update 事件讲完。
     */
    private _emitTaskAutoStart(entry: NotificationEntry): void {
        if (entry.type !== "task" || entry.startEmitted) return;
        if ((entry.props as any).canStart === true) return;
        const st = (entry.instance?.data as any)?.state;
        if (st === "stopped" || st === "completed") return;
        entry.startEmitted = true;
        this._emitControlAction(entry.props.id, "start");
    }

    // ── 事件（决策 20 → ADR-0102 分层命名） ────────────────────────

    /**
     * 双通道事件（决策 20 → ADR-0102）：引擎总线 + 卡片元素 dispatchEvent，均以**具体名**
     * `notifications/<type>/<id>/<verb>` 广播（订阅面可 `*`/`**` 通配，emit 面恒具体——
     * `components/<名>/registered` 动态键先例）。payload `{ notification: 组件实例, el }`。
     */
    _emit(
        verb: "add" | "update" | "show" | "hide" | "read" | "status",
        entry: NotificationEntry,
    ): void {
        const name = notificationEventName(entry.type, entry.props.id, verb);
        const detail = { notification: entry.instance as ComponentInstance, el: entry.el };
        this.engine.emit(name, detail as any);
        entry.el?.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
    }

    /**
     * action 事件（`notifications/<type>/<id>/actions/<名>`）：末段 = action id（字符串形态 =
     * action id / 对象形态 = `id` ?? `title`）；payload 额外 `action`/`value`；anchor 存在时
     * 以发起子树为根额外派发（决策 14 职责②）。
     */
    _emitAction(entry: NotificationEntry, action: ResolvedNotificationAction): void {
        const name = notificationEventName(entry.type, entry.props.id, `actions/${action.name}`);
        const detail = {
            notification: entry.instance as ComponentInstance,
            el: entry.el,
            action: { title: action.title, hide: action.hide },
            value: action.hasValue ? action.value : undefined,
        };
        this.engine.emit(name, detail as any);
        entry.el?.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
        if (entry.anchor) {
            entry.anchor.dispatchEvent(new CustomEvent(name, { detail, bubbles: true }));
        }
    }

    // ── delayClose 计时与 hover 暂停（剩余时间制 + remaining 约定键联动） ──


    /** 启动自动关闭计时（holdOpen 约定键拦截——true 期间不计时，ADR-0089 决策五） */
    _startTimer(entry: NotificationEntry): void {
        this._clearTimer(entry);
        if (entry.instance?.data.holdOpen === true) return; // 进行中 sticky（task 未完成等）
        const delay = entry.props.delayClose;
        if (typeof delay === "number" && delay > 0) {
            entry.deadline = Date.now() + delay;
            entry.pausedRemaining = null;
            if (entry.instance) entry.instance.data.remaining = delay;
            entry.tickTimer = setInterval(() => {
                if (entry.deadline != null && entry.instance) {
                    entry.instance.data.remaining = Math.max(0, entry.deadline - Date.now());
                }
            }, 1000);
            entry.timer = setTimeout(() => {
                entry.timer = null;
                this._dismiss(entry, true);
            }, delay);
        } else {
            entry.deadline = null; // sticky
            if (entry.instance) entry.instance.data.remaining = -1;
        }
    }

    /** hover 暂停：记剩余时间、停表与 tick（sticky 无表 no-op） */
    _pauseTimer(entry: NotificationEntry): void {
        if (entry.timer == null || entry.deadline == null) return;
        clearTimeout(entry.timer);
        entry.timer = null;
        entry.pausedRemaining = Math.max(0, entry.deadline - Date.now());
    }

    /** hover 移出恢复：按剩余时间续表 */
    _resumeTimer(entry: NotificationEntry): void {
        if (entry.pausedRemaining == null || entry.state !== "shown") return;
        const remaining = entry.pausedRemaining;
        entry.pausedRemaining = null;
        entry.deadline = Date.now() + remaining;
        entry.timer = setTimeout(() => {
            entry.timer = null;
            this._dismiss(entry, true);
        }, remaining);
    }

    _clearTimer(entry: NotificationEntry): void {
        if (entry.timer != null) {
            clearTimeout(entry.timer);
            entry.timer = null;
        }
        if (entry.tickTimer != null) {
            clearInterval(entry.tickTimer);
            entry.tickTimer = null;
        }
        entry.pausedRemaining = null;
    }
}
